public static int countDoubles(int[] numbers) {
    // Count occurrences of each number
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }

    int count = 0;
    for (int num : numbers) {
        if (num % 2 != 0) {
            continue; // odd numbers cannot be twice another integer
        }
        int half = num / 2;
        Integer halfCount = freq.get(half);
        if (halfCount == null) {
            continue; // no such half in the list
        }
        // If half equals num, need at least two occurrences
        if (half == num) {
            if (halfCount > 1) {
                count++;
            }
        } else {
            count++;
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (Arrays.equals(start, end)) return "can be travelled";
    Map<String, List<String>> adj = new HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) continue;
        String a = Arrays.toString(Arrays.copyOfRange(path, 0, n));
        String b = Arrays.toString(Arrays.copyOfRange(path, n, 2 * n));
        adj.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
    }
    String startKey = Arrays.toString(start);
    String endKey = Arrays.toString(end);
    if (!adj.containsKey(startKey) || !adj.containsKey(endKey)) return "cannot be travelled";
    Set<String> visited = new HashSet<>();
    Deque<String> queue = new ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) return "can be travelled";
        for (String nb : adj.getOrDefault(cur, Collections.emptyList())) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

