public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    for (int r = 1; r < k; r++) {
        if (freq[r] != freq[(k - r) % k]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.ArrayList<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int neighbor : graph[node]) {
            if (neighbor != parent[node]) {
                parent[neighbor] = node;
                stack.push(neighbor);
            }
        }
    }
    int[] time = new int[n];
    for (int i = idx - 1; i >= 0; i--) {
        int node = order[i];
        for (int neighbor : graph[node]) {
            if (neighbor != parent[node]) {
                if (time[neighbor] > 0 || hasApple[neighbor]) {
                    time[node] += time[neighbor] + 2;
                }
            }
        }
    }
    return time[0];
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder();
    int total = s.length();
    while (sb.length() < total) {
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
            }
        }
        // Descending pass
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[maxK + 1];
    for (int k = 0; k <= maxK; k++) dp[k] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

