public static int singleNumber(int[] nums) {
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i > high) break;
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int) num);
        }
        if (num > high) continue;
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) queue.offer(next);
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) queue.offer(next);
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    int count = 0;
    for (int factor = 1; factor <= n; factor *= 10) {
        int high = n / (factor * 10);
        int cur = (n / factor) % 10;
        int low = n % factor;
        count += high * factor;
        if (cur == 1) {
            count += low + 1;
        } else if (cur > 1) {
            count += factor;
        }
    }
    return count;
}

