public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][][] dp = new int[m][n][4];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;          // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;          // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // diagonal
                dp[i][j][3] = (i > 0 && j + 1 < n ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal
                int localMax = Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                         Math.max(dp[i][j][2], dp[i][j][3]));
                if (localMax > max) {
                    max = localMax;
                }
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    boolean negative = n < 0;
    long num = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (num > 0) {
        sb.append(num % 10);
        num /= 10;
        count++;
        if (num > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        int n = A.length;
        java.util.Arrays.sort(A);
        boolean[] used = new boolean[n];
        return dfs(0, -1, A, used);
    }

    private static int dfs(int depth, int last, int[] A, boolean[] used) {
        if (depth == A.length) return 1;
        int count = 0;
        for (int i = 0; i < A.length; i++) {
            if (used[i]) continue;
            if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
            if (last == -1 || isSquare(A[last] + A[i])) {
                used[i] = true;
                count += dfs(depth + 1, i, A, used);
                used[i] = false;
            }
        }
        return count;
    }

    private static boolean isSquare(int sum) {
        int sqrt = (int) Math.sqrt(sum);
        return sqrt * sqrt == sum;
    }
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        if (sum % 2 == 0) {
            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Find the first index from the end where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // No higher permutation exists
        return -1;
    }
    // Find the smallest digit on the right side of i that is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the subarray from i+1 to end
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    return Integer.parseInt(new String(digits));
}

