public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check that all points are distinct
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    // Compute the area of the triangle formed by the three points
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];
    int area2 = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int curr, int n, List<Integer> res) {
    if (curr > n) return;
    res.add(curr);
    for (int d = 0; d < 10; d++) {
        long next = (long) curr * 10 + d;
        if (next > n) break;
        dfs((int) next, n, res);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            result.append(' ');
            word.setLength(0);
        } else {
            word.append(c);
        }
    }
    // Append the last word
    result.append(word.reverse());
    return result.toString();
}
